#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *mode = argv[1];
    const char *input = argv[2];
    char out[1024];
    size_t out_idx = 0;

    if (strcmp(mode, "to_camel") == 0) {
        int capitalize = 0;
        for (size_t i = 0; input[i] && out_idx < sizeof(out) - 1; ++i) {
            char c = input[i];
            if (c == '_') {
                capitalize = 1; // next character will be upper case
                continue;
            }
            if (capitalize) {
                out[out_idx++] = (char)toupper((unsigned char)c);
                capitalize = 0;
            } else {
                out[out_idx++] = c;
            }
        }
        out[out_idx] = '\0';
        puts(out);
    } else if (strcmp(mode, "to_snake") == 0) {
        for (size_t i = 0; input[i] && out_idx < sizeof(out) - 1; ++i) {
            char c = input[i];
            if (isupper((unsigned char)c)) {
                if (i != 0) {
                    out[out_idx++] = '_';
                }
                out[out_idx++] = (char)tolower((unsigned char)c);
            } else {
                out[out_idx++] = c;
            }
        }
        out[out_idx] = '\0';
        puts(out);
    } else {
        puts("INVALID_MODE");
    }
    return 0;
}
